/* Briques d'interface et écrans */
const hue=id=>[...id].reduce((a,c)=>a+c.charCodeAt(0)*7,0)%360;
const ini=id=>M[id].n.split(' ').map(w=>w[0]).join('').slice(0,2);
const av=(id,c='')=>id==='club'?`<span class="av club ${c} ${club().logo?'logo':''}" ${club().logo?`style="background-image:url(${club().logo})"`:''}>${club().logo?'':club().short}</span>`:M[id].photo?`<span class="av ${c}${frc(id)}" style="background-image:url(${M[id].photo})"></span>`:`<span class="av ${c}${frc(id)}" style="--h:${hue(id)}">${ini(id)}</span>`;
/* Jamais d'âge affiché : une catégorie à la place (U12, Senior, +45…) */
const catOf=id=>{const a=age(id);if(a<18)return 'U'+(Math.floor(a/2)*2+2);if(a<35)return 'Senior';return '+'+(a>=75?75:a>=65?65:a>=55?55:a>=45?45:35)};
const seesMinors=()=>isAdmin()||S.role==='coach';
/* Les résultats d'un jeune ne sont visibles que de lui, de son groupe, de ses parents et des encadrants */
const kidOk=k=>ME()===k||seesMinors()||(M[ME()].kids||[]).includes(k)||GROUPS.some(g=>g.type==='train'&&g.mem.includes(k)&&g.mem.includes(ME()));
const RC={Club:'club',Enseignante:'coach',Enseignant:'coach',Président:'pres',Capitaine:'cap'};
/* Un seul classement par personne, choisi selon le sport de l'écran */
const rk=(id,sport)=>{const m=M[id],tn=m.r&&m.r!=='NC'?m.r+' Tennis':'',pd=m.pl?'Niv '+m.pl+' Padel':'';return sport==='Padel'?(pd||tn):(tn||pd)};
function bd(id,sport){if(id==='club')return '<span class="bds"><span class="bd club">Club</span></span>';const m=M[id],r=rk(id,sport);
 return `<span class="bds">${m.role?`<span class="bd ${RC[m.role]||''}">${m.role}</span>`:''}${r?`<span class="bd rk">${r}</span>`:''}</span>`}
const who=id=>id==='club'||id===ME()?`<span class="nm">${name(id)}</span>`:`<button class="nm" data-a="member" data-id="${id}">${name(id)}</button>`;
const view=()=>S.stack.length?S.stack[S.stack.length-1]:{v:S.tab};
const segs=(k,tabs)=>`<div class="seg" role="tablist">${tabs.map(t=>`<button role="tab" aria-selected="${S[k]===t[0]}" data-a="seg" data-k="${k}" data-val="${t[0]}">${t[2]?ic(t[2]):''}${t[1]}</button>`).join('')}</div>`;
const sportTag=s=>s?`<span class="tag ${s==='Padel'?'padel':'tennis'}">${s}</span>`:'';
function teamTags(tid){const g=grp(tid),c=champOf(g);if(!c)return '';return sportTag(c.sport)+`<span class="tag ${g.gen==='Femmes'?'f':''}">${g.gen}</span><span class="tag">${c.age}</span>`}
const stPill=r=>r.st==='live'?'<span class="live"><i></i>En direct</span>':r.st==='done'?'<span class="bd">Terminé</span>':'<span class="bd">À venir</span>';
const empty=(icn,t,s)=>`<div class="empty">${ic(icn)}<span class="nm" style="color:var(--fg)">${t}</span><span class="small">${s||''}</span></div>`;
const gallery=ph=>ph&&ph.length?`<div class="gal ${ph.length===1?'one':''}">${ph.map((u,i)=>`<button class="ph" style="background-image:url(${u})" data-a="photo" aria-label="Photo ${i+1} sur ${ph.length}"></button>`).join('')}</div>`:'';

function recCard(r){const g=grp(r.tid),s=teamScore(r);
 return `<button class="rec" data-a="open" data-v="rec" data-id="${r.id}"><span class="row" style="justify-content:space-between"><span class="tags">${teamTags(r.tid)}</span>${stPill(r)}</span>
 <span class="vs"><span class="t">${teamName(g)}<br><span class="muted small" style="font-weight:500">${club().name}</span></span><span class="n" data-live2="${r.id}">${r.st==='soon'?'–':`<b>${s[0]}</b> · ${s[1]}`}</span><span class="t">${r.opp}</span></span>
 <span class="muted small">${r.comp} · ${r.when}</span></button>`}

/* ---------- publications ---------- */
function postSport(p){if(p.sport)return p.sport;if(p.play)return p.play.sport;if(p.rec){const r=recs.find(r=>r.id===p.rec);return r?recSport(r):''}if(p.art){const a=arts.find(a=>a.id===p.art);return a&&a.sport||''}return ''}
/* Règles de visibilité : appliquées à tous sauf au bureau, qui voit tout */
function ruleOk(rule){if(!rule||isAdmin())return true;const v=M[ME()],a=age(ME());
 if(rule.pub==='Bureau uniquement')return false;
 if(rule.pub==='Équipe pédagogique'&&!(v.role||'').startsWith('Enseignant'))return false;
 if(rule.pub==='Parents'&&!(v.kids&&v.kids.length))return false;
 if((rule.gen==='Hommes'&&v.g!=='H')||(rule.gen==='Femmes'&&v.g!=='F'))return false;
 if((rule.age==='Jeunes'&&a>=18)||(rule.age==='Adultes'&&a<18))return false;
 if((rule.prat==='Compétiteurs'&&v.r==='NC')||(rule.prat==='Loisir'&&v.r!=='NC'))return false;
 if(rule.tn||rule.pd){const t=rule.tn&&rIdx(v.r)>=rule.tn[0]&&rIdx(v.r)<=rule.tn[1],p=rule.pd&&v.pl!=null&&v.pl>=rule.pd[0]&&v.pl<=rule.pd[1];if(!t&&!p)return false}
 return true}
/* Publications d'un jeune : visibles de son groupe et de ses encadrants, ou de tout le club pour ses résultats si un parent l'a choisi */
function canSee(p){if(p.arch||S.blocked.has(p.by)||!ruleOk(p.rule))return false;if(isMinor(p.by)&&!kidOk(p.by)&&!((p.kind==='perf'||p.kind==='padel')&&M[p.by].resVis==='club'))return false;
 if(p.art){const a=arts.find(a=>a.id===p.art);if(!a||a.arch)return false}
 if(p.rec){const r=recs.find(r=>r.id===p.rec);if(!r||r.arch)return false}
 if(p.kind!=='play'||p.by===ME())return true;if(S.role==='kid')return false;const y=p.play,v=M[ME()];
 if(y.sport==='Padel')return v.pl!=null&&v.pl>=y.lo&&v.pl<=y.hi;
 return rIdx(v.r)>=rIdx(y.lo)&&rIdx(v.r)<=rIdx(y.hi)}
const shortDate=p=>{if(!p.d)return p.date;const a=p.d.split('-').map(Number),b=p.d2&&p.d2.split('-').map(Number);return b?`${a[2]} ${MO[a[1]-1]} → ${b[2]} ${MO[b[1]-1]}`:`${a[2]} ${MO[a[1]-1]}`};

function evBox(p){const y=(p.yes||0)+(p.my==='yes'?1:0),m=(p.maybe||0)+(p.my==='maybe'?1:0),wl=(p.wl||0)+(p.my==='wait'?1:0),int=p.reg!=='ext',past=p.done||p.arch,full=p.cap&&y>=p.cap&&p.my!=='yes',
  meta=`<div class="meta"><span>${ic('clock')}${p.date}</span><span>${ic('pin')}${p.place}</span></div>`,
  cnt=int?`<div class="cnts"><span><b>${y}${p.cap&&!past?'/'+p.cap:''}</b>${past?'participant':'inscrit'}${y>1?'s':''}</span>${past?'':`<span><b>${m}</b>peut-être</span>`}${wl&&!past?`<span><b>${wl}</b>en attente</span>`:''}</div>`:'';
 if(past)return `<div class="ev">${meta}${cnt}${p.arch?`<span class="muted small">Archivé · saison ${p.arch}</span>`:''}</div>${p.done&&p.done.txt?`<p><b>Le mot du club.</b> ${p.done.txt}</p>`:''}${p.done?gallery(p.done.photos):''}`;
 const reg=!int?`<a class="btn full" href="${p.tenup||'https://tenup.fft.fr'}" target="_blank" rel="noopener">S'inscrire sur Ten'Up ${ic('link')}</a><span class="muted small">L'inscription se fait sur Ten'Up, le site de la FFT. Le lien s'ouvre en dehors de l'appli.</span>`
  :cnt+(p.closed?`<span class="btn ext full" aria-disabled="true">Inscriptions closes</span>${p.my==='yes'?'<span class="muted small">Tu fais partie des inscrits.</span>':''}`
  :full?`<div class="ctl"><button class="btn grow" disabled>Complet</button><button class="btn grow ${p.my==='wait'?'on':'ghost'}" data-a="rsvp" data-id="${p.id}" data-r="wait">${p.my==='wait'?"Quitter l'attente":"Liste d'attente"}</button></div>`
  :`<div class="ctl"><button class="btn grow ${p.my==='yes'?'on':''}" data-a="rsvp" data-id="${p.id}" data-r="yes">${p.my==='yes'?'Je me désinscris':"Je m'inscris"}</button><button class="btn grow ${p.my==='maybe'?'on':'ghost'}" data-a="rsvp" data-id="${p.id}" data-r="maybe" aria-pressed="${p.my==='maybe'}">Peut-être</button></div>`);
 const vol=int&&!p.comm?`<div class="volu"><span class="grow small">${(p.vol||[]).length?`<b>${p.vol.length} bénévole${p.vol.length>1?'s':''}</b> · `:''}Tu veux aider à l'organisation ?</span><button class="btn sm ${(p.vol||[]).includes(ME())?'on':'ghost'}" data-a="volu" data-id="${p.id}">${(p.vol||[]).includes(ME())?'Je suis bénévole':"Je m'inscris comme bénévole"}</button></div>`:'';
 return `<div class="ev">${meta}${reg}${vol}${p.pay?`<a class="btn ghost full" href="${p.pay}" target="_blank" rel="noopener">Payer en ligne ${ic('link')}</a>`:''}<button class="btn sm ghost" data-a="ics" data-id="${p.id}">${ic('cal')}Ajouter à mon agenda</button></div>`}

/* Fiche d'un tournoi : tableau, catégorie, classements, limite de participants, fin des inscriptions */
const trnAge=t=>t.pub==='Jeunes'?`${t.a1} à ${t.a2} ans`:t.pub==='Seniors +'?t.vet:'Seniors';
function trnBox(p){const t=p.trn,pad=t.sport==='Padel',row=(l,v)=>`<div class="price"><span class="muted">${l}</span><b class="tv">${v}</b></div>`,past=t.dl&&t.dl<TODAY;
 return `<div class="card" style="background:var(--card2);gap:8px"><div class="tags" style="display:flex">${sportTag(t.sport)}<span class="tag ${t.gen==='Femmes'?'f':''}">${t.gen}</span><span class="tag">${trnAge(t)}</span>${pad?`<span class="tag padel">${t.cat}</span>`:`<span class="tag">${t.fmt}</span><span class="tag">${t.open?'Open':'Limité'}</span>`}</div>
 <div>${row('Tableau',t.gen)}${row('Catégorie',trnAge(t))}${pad?row('Catégorie de tournoi',t.cat):row('Format',t.fmt==='TMC'?'TMC (multi-chances)':'Traditionnel')+row('Classements',t.open?'Open, tous classements':t.lo+' à '+t.hi)}${row('Participants',t.max?t.max+' '+(pad?'paires':'joueurs')+' maximum':'Sans limite')}${row('Fin des inscriptions',t.dl?fmtD(t.dl)+(past?' · terminé':''):'Non précisée')}</div></div>`}
function postBody(p){const k=p.kind;if(k==='teamfinal')return tfPost(p);
 if(k==='annonce'||k==='event'||k==='cta'){const usePoster=p.img||k==='event';
  return (usePoster?`<div class="poster ${p.img?'photo':''}" ${p.img?`style="background-image:url(${p.img})" data-a="photo" role="button" tabindex="0" aria-label="Agrandir la photo"`:''}>${p.done?'<span class="bd done">Terminé</span>':''}<span class="kicker" style="color:var(--fg)">${k==='event'?(p.trn?'Tournoi · '+p.trn.sport:'Événement'):club().name}</span><span class="big">${p.title}</span>${k==='event'?`<span class="datepill">${ic('cal')}${shortDate(p)}</span>`:''}</div>`:`<h2 class="tilt sm">${p.title}<i class="dd"></i></h2>`)
  +`<p>${p.body}</p>${k==='event'?(p.trn?trnBox(p):'')+evBox(p):''}${k==='cta'?`<a class="btn full" href="${p.url}" target="_blank" rel="noopener">${p.label} ${ic('link')}</a><span class="muted small">Ouvre ${p.url.replace(/^https?:\/\//,'').split('/')[0]} en dehors de l'appli.</span>`:''}`}
 if(k==='comm'){const c=COMMS.find(c=>c.id===p.comm),y=(p.yes||0)+(p.my==='yes'?1:0),m=(p.maybe||0)+(p.my==='maybe'?1:0);
  return `<div class="poster ${p.img?'photo':''}" ${p.img?`style="background-image:url(${p.img})" data-a="photo" role="button" tabindex="0" aria-label="Agrandir la photo"`:''}><span class="kicker" style="color:var(--fg)">Commission</span><span class="big">${p.title}</span></div><p>${p.body}</p><div class="cnts"><span><b>${y}</b>intéressé${y>1?'s':''}</span><span><b>${m}</b>peut-être</span></div>
  <div class="ctl"><button class="btn grow ${p.my==='yes'?'on':''}" data-a="rsvp" data-id="${p.id}" data-r="yes">${p.my==='yes'?'Intéressé':"Ça m'intéresse"}</button><button class="btn grow ${p.my==='maybe'?'on':'ghost'}" data-a="rsvp" data-id="${p.id}" data-r="maybe">Peut-être</button></div>${c?`<button class="btn sm ghost" data-a="open" data-v="comm" data-id="${c.id}">Voir la ${c.name.toLowerCase()}</button>`:''}`}
 if(k==='padel'){const r=p.pres;return `<div class="perf"><span class="stamp ${r.place==='1er'?'':'win'}">${r.place==='1er'?'Titre !':r.place}</span><span class="kicker">Tournoi de padel · ${r.cat}${r.age?' · '+r.age:r.pub!=='Adultes'?' · '+r.pub:''}</span><span class="sc">${r.place==='1er'?'1re':r.place} place</span><span>${partnerTxt(r)} · ${r.club}, ${fmtD(r.d)}</span></div>`}
 if(k==='perf'){const r=p.res;return `<div class="perf ${r.w?'':'lost'}"><span class="stamp ${r.perf?'':r.w?'win':'lose'}">${r.fin?(r.w?'Titre !':'Finaliste'):r.perf?'Perf !':r.w?'Victoire':'Défaite'}</span><span class="kicker">${esc(r.ctx)}</span><span class="sc">${esc(r.sc)}</span><span>${r.w?'Victoire':'Défaite'} contre <b>${esc(r.opp)}</b> <span class="bd rk">${esc(r.or)}</span></span></div>`}
 if(k==='play'){const y=p.play,inn=y.in.includes(ME()),full=y.in.length>=y.places,wt=y.wait.includes(ME());
  return `<span class="kicker">Recherche de partie · ${y.sport}</span><h2 class="tilt sm">${y.fmt} <em>${y.sport==='Padel'?'niveau '+y.lo+' à '+y.hi:y.lo+' à '+y.hi}</em></h2><div class="ev"><div class="meta"><span>${ic('cal')}${y.date} · ${y.time}</span><span>${ic('clock')}${y.dur}</span></div>
  <div class="row"><span class="dots" aria-hidden="true">${Array.from({length:y.places},(_,i)=>`<i class="${i<y.in.length?'on':''}"></i>`).join('')}</span><span>${y.in.length} place${y.in.length>1?'s':''} prise${y.in.length>1?'s':''} sur ${y.places}${y.wait.length?` · ${y.wait.length} en attente`:''}</span></div>
  ${y.in.length?`<div class="row" style="flex-wrap:wrap;gap:6px 12px">${y.in.map(i=>`<span class="row" style="gap:6px">${av(i,'sm')}${name(i)}</span>`).join('')}</div>`:''}`+
  (p.by===ME()?`<span class="muted small">Ta recherche reste en ligne jusqu'au créneau. Seuls les joueurs de cette fourchette la voient.</span>`
  :`<div class="ctl">${inn?`<button class="btn on grow" data-a="play" data-id="${p.id}" data-r="in">Je ne peux plus</button>`:full?`<button class="btn grow" disabled>Complet</button><button class="btn ${wt?'on':'ghost'} grow" data-a="play" data-id="${p.id}" data-r="wait" aria-pressed="${wt}">${wt?"Quitter l'attente":"Liste d'attente"}</button>`:`<button class="btn grow" data-a="play" data-id="${p.id}" data-r="in">Compte sur moi</button>`}</div>`)+`</div>`}
 if(k==='poll'){const tot=p.opts.reduce((a,o,i)=>a+o[1]+(p.my===i?1:0),0),closed=p.close&&p.close<TODAY;
  return `<span class="kicker">Sondage${closed?' · clos':p.close?' · jusqu\'au '+fmtD(p.close):''}</span><h2 class="h3">${p.q}</h2><div class="poll">${p.opts.map((o,i)=>{const n=o[1]+(p.my===i?1:0),pc=tot?Math.round(n*100/tot):0;return `<button class="opt" style="--p:${pc}%" ${closed?'disabled':`data-a="vote" data-id="${p.id}" data-i="${i}"`} aria-pressed="${p.my===i}"><i></i><span>${o[0]}</span><span>${pc} %</span></button>`}).join('')}</div><span class="muted small">${tot} vote${tot>1?'s':''} · ${closed?'le sondage est clos':p.my===null?'touche une réponse pour voter':'touche ta réponse pour la retirer'}</span>`}
 if(k==='match'||k==='result'){const r=recs.find(r=>r.id===p.rec),g=grp(r.tid),s=teamScore(r),w=s[0]>s[1],d=s[0]===s[1];
  return (k==='result'?`<button class="rlink" data-a="open" data-v="rec" data-id="${r.id}"><span class="kicker">Résultat publié automatiquement</span><h2 class="tilt sm">${d?'Match nul':w?'Victoire':'Défaite'} <em>${s[0]} à ${s[1]}</em><i class="dd"></i></h2><p>${teamName(g)} ${d?'partage les points avec':w?"s'impose contre":"s'incline contre"} ${r.opp}. ${w?'Félicite les joueurs en commentaire.':"Un mot d'encouragement en commentaire leur fera plaisir."}</p><span class="nm" style="color:var(--accent)">Voir le détail des matchs ${ic('back')}</span></button>`:`<p>${p.body}</p>`)
  +(r.img?`<button class="ph wide" style="background-image:url(${r.img})" data-a="photo" aria-label="Photo d'équipe"></button>`:'')+recCard(r)}
 if(k==='journal'){const a=arts.find(a=>a.id===p.art);return `<button class="teaser" data-a="open" data-v="art" data-id="${a.id}">${a.img?`<span class="ph wide" style="background-image:url(${a.img})"></span>`:''}<span class="kicker">Actus du club · ${a.cat}</span><span class="h3">${a.title}</span><span class="muted">${a.lead}</span><span class="nm" style="color:var(--accent)">Lire l'actu</span></button>`}
 return ''}
/* Bandeau partenaires : pas une publication, une frise colorée qui défile */
const plogo=(x,c)=>x.logo?`<img class="${c||''}" src="${x.logo}" alt="" style="${x.dark?'background:#0B0B0B;padding:4px':''}">`:`<span class="adl ${c||''}">${x.name.split(' ').filter(w=>w.length>2).map(w=>w[0]).join('').slice(0,2)}</span>`;
function adBand(p){const ps=p.partners.map(id=>PARTNERS.find(x=>x.id===id)).filter(Boolean);if(!ps.length)return '';
 const items=ps.map(x=>`<button class="adi" data-a="open" data-v="partners">${plogo(x)}<span>${x.name}</span></button>`).join('');
 return `<section class="adband ${p.color==='hot'?'hot':''}" aria-label="${esc(p.title)}"><div class="adh"><span>${p.title}</span>${isAdmin()?`<button class="ib" data-a="pmenu" data-id="${p.id}" aria-label="Options du bandeau">${ic('more')}</button>`:''}</div><div class="adw"><div class="track">${items}${items.replace(/<button /g,'<button tabindex="-1" aria-hidden="true" ')}</div></div></section>`}
function commList(){const can=c=>isBureau()||c.resp===ME();
 return `<div class="pad"><p class="muted">Les commissions font vivre le club. Touche une commission pour voir ses membres et demander à la rejoindre.</p>${COMMS.map(c=>`<button class="card" data-a="open" data-v="comm" data-id="${c.id}" style="width:100%;text-align:left"><span class="row"><span class="tile">${ic('users')}</span><span class="grow"><span class="h3">${c.name}</span><br><span class="muted small">Responsable : ${name(c.resp)} · ${c.mem.length} membre${c.mem.length>1?'s':''}</span></span>${can(c)&&c.req.length?`<span class="un" style="background:var(--hot);color:var(--on-hot)">${c.req.length}</span>`:''}</span><span class="muted small">${c.desc}</span></button>`).join('')}${isBureau()?`<button class="btn full ghost" data-a="newPost" data-k="comm">Créer une commission</button>`:''}</div>`}
function postHTML(p){if(p.kind==='ad')return adBand(p);const liked=S.liked.has(p.id),sp=postSport(p);
 return `<article class="post">${sp?`<span class="sp ${sp==='Padel'?'padel':''}">${sp}</span>`:''}<div class="hd">${av(p.by)}<div class="grow"><div class="row" style="gap:6px;flex-wrap:wrap">${who(p.by)}${bd(p.by,sp)}</div><div class="muted small">${p.pin?'<span class="bd pin">Épinglé</span> ':''}${p.t}</div></div><button class="ib" data-a="pmenu" data-id="${p.id}" aria-label="Options de la publication">${ic('more')}</button></div>
 ${isAdmin()&&p.vis&&p.vis.length?`<div class="vis">${ic('eye')}Visible par ${p.vis.map(v=>`<span class="tag">${v}</span>`).join('')}</div>`:''}${isMinor(p.by)?`<div class="vis">${ic('shield')}Visible par son groupe, ses parents et les encadrants</div>`:''}${postBody(p)}
 <div class="acts"><button class="act ${liked?'on':''} ${S.pop===p.id?'pop':''}" data-a="like" data-id="${p.id}" aria-pressed="${liked}" aria-label="J'aime">${ic('heart')}${p.likes+(liked?1:0)}</button><button class="act" data-a="comments" data-id="${p.id}" aria-label="Commentaires">${ic('com')}${p.com.length}</button></div></article>`}
/* Message : le texte est lu par les lecteurs d'écran ; un appui ouvre réactions, réponse, signalement */
/* Aide à l'appui long : affichée jusqu'à la première utilisation (mémorisée sur l'appareil) */
const lpHelp=()=>{let seen=false;try{seen=localStorage.getItem('club-lp-help')==='1'}catch(e){}return seen?'':'<p class="muted small lphelp" id="lp-help">Reste appuyé sur un message pour réagir, répondre ou le signaler.</p>'};
/* Messages façon WhatsApp : une bulle carrée qui contient le nom, les badges, le message et l'heure ; seul l'avatar reste dehors.
   Quand la même personne enchaîne (moins de 5 min d'écart), ni avatar, ni nom : les bulles s'empilent. Mes messages : à droite, sans avatar ni nom. */
const msgCont=(l,i)=>{const m=l[i],p=l[i-1];return !!p&&p.by===m.by&&!S.blocked.has(p.by)&&!(m.at&&p.at&&m.at-p.at>3e5)};
/* Séparateur de jour entre les messages : Aujourd'hui, Hier, Lundi, 14 oct */
const dayOf=at=>{const d=new Date(at);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
function dayLbl(at){const d=dayOf(at),t=new Date(),n=Math.round((new Date(dayOf(+t))-new Date(d))/864e5);return n===0?"Aujourd'hui":n===1?'Hier':n<7?DAYS[new Date(at).getDay()]:fmtD(d)}
const msgRow=(m,i,sport,ref,fresh)=>{if(S.blocked.has(m.by))return '';const l=msgList(ref)||[],p=l[i-1],newDay=m.at&&(!p||!p.at||dayOf(p.at)!==dayOf(m.at)),cont=!newDay&&l[i]===m&&msgCont(l,i),mine=m.by===ME(),pop=fresh||m._pop;delete m._pop;
 return `${newDay?`<div class="daysep"><span>${dayLbl(m.at)}</span></div>`:''}<div class="msg ${mine?'me':''} ${cont?'cont':''} ${pop?'in':''}">${mine?'':cont?'<span class="avsp" aria-hidden="true"></span>':av(m.by,'sm')}<div class="grow"><div class="bubw"><div class="bub" data-lp="mmenu" data-ref="${ref}" data-i="${i}">${mine||cont?'':`<div class="hd">${who(m.by)}${bd(m.by,sport)}</div>`}${m.rep?`<span class="quote">${m.rep.by==='club'?club().short:first(m.rep.by)} : ${esc(m.rep.x).slice(0,80)}</span>`:''}${m.img?`<button class="ph mph" style="background-image:url(${m.img})" data-a="photo" aria-label="Agrandir la photo"></button>`:''}${m.x?`<span class="tx">${esc(m.x)}</span>`:''}<time>${m.t||''}</time></div><button class="bmore" data-a="mmenu" data-ref="${ref}" data-i="${i}" aria-label="Options du message">${ic('more')}</button></div>${m.re&&Object.keys(m.re).length?`<div class="reacts">${Object.entries(m.re).map(([e,n])=>`<button class="react ${m.my===e?'on':''}" data-a="react" data-ref="${ref}" data-i="${i}" data-e="${e}" aria-label="Réaction ${e}, ${n}">${e} ${n}</button>`).join('')}</div>`:''}</div></div>`};
const muteBtn=c=>`<button class="ib ${c.mute?'off':''}" data-a="mute" data-id="${c.id}" aria-pressed="${!!c.mute}" aria-label="${c.mute?'Réactiver les notifications de '+c.name:'Mettre '+c.name+' en sourdine'}">${ic(c.mute?'mute':'sound')}</button>`;
/* Un compte jeune ne voit que les annonces et les canaux de son groupe */
const chanOk=c=>S.role!=='kid'||c.id==='annonces'||c.kid;

/* ---------- rencontre ---------- */
function recView(id){const r=recs.find(r=>r.id===id),g=grp(r.tid),sport=recSport(r),s=teamScore(r),live=r.st==='live',can=canTeam(g),me=ME();
 let h=`<div class="pad"><div class="hero"><div class="row" style="justify-content:space-between"><span class="tags">${teamTags(r.tid)}</span>${stPill(r)}</div><span class="kicker">${r.comp}</span>
 <div class="vs"><span class="t"><span class="cl" style="vertical-align:-4px">${ic('home')}</span> ${teamName(g)}</span><span class="n">${r.st==='soon'?'–':`<b>${s[0]}</b> · ${s[1]}`}</span><span class="t">${r.opp}</span></div><span class="muted small">${r.when}</span></div>`;
 if(r.img)h+=`<button class="ph wide" style="background-image:url(${r.img})" data-a="photo" aria-label="Photo d'équipe"></button>`;
 if(r.ms){
  h+=`<div class="row" style="justify-content:space-between"><span class="legend"><span class="cl">${ic('home')}</span>Joueur de ${club().name}</span>${live&&can?`<button class="btn sm ${S.scoring?'on':''}" data-a="scoring">${S.scoring?'Quitter la saisie':'Saisir les scores'}</button>`:''}</div>`;
  h+=r.ms.map((m,i)=>{const cur=m.sets.length-1;
   const line=side=>{const b2=x=>x?`<span class="bd rk">${x}</span>`:'';
    const pl=side===0?`<span class="cl">${ic('home')}</span>`+(m.a?`${who(m.a)}${b2(sport==='Padel'&&M[m.a].pl?'Niv '+M[m.a].pl:M[m.a].r)}`:`<span class="nm">${m.an}</span>${b2(m.ar)}`):`<span class="cl none"></span><span class="o">${esc(m.b[0])}</span>${b2(m.b[1])}`;
    const cells=[0,1,2].map(k=>{const st=m.sets[k];if(!st)return '<span class="s e">–</span>';const w=st[side]>st[1-side],isCur=m.st==='live'&&k===cur,fl=S.flash&&S.flash[0]===i&&S.flash[1]===side&&S.flash[2]===k;return `<span class="s ${isCur?'cur':w?'w':''} ${fl?'flash':''}">${st[side]}</span>`}).join('');
    return `<div class="line ${side?'away':''}"><span class="who">${pl}</span>${cells}</div>`};
   let ctl='';
   if(live&&S.scoring&&m.st==='live')ctl=`<div class="ctl"><button class="btn sm ghost" data-a="ungame" data-r="${r.id}" data-i="${i}" data-s="0" aria-label="Retirer un jeu à ${club().short}">−1</button><button class="btn sm grow" data-a="game" data-r="${r.id}" data-i="${i}" data-s="0">+1 ${club().short}</button><button class="btn sm ghost grow" data-a="game" data-r="${r.id}" data-i="${i}" data-s="1">+1 adversaire</button><button class="btn sm ghost" data-a="ungame" data-r="${r.id}" data-i="${i}" data-s="1" aria-label="Retirer un jeu à l'adversaire">−1</button></div>`;
   if(live&&S.scoring&&m.st==='done')ctl=`<button class="btn sm ghost" data-a="ungame" data-r="${r.id}" data-i="${i}" data-s="${m.w}">Corriger : retirer le dernier jeu</button>`;
   if(live&&S.scoring&&m.st==='soon')ctl=`<button class="btn sm ghost" data-a="start" data-r="${r.id}" data-i="${i}">Lancer le match</button>`;
   return `<div class="board"><div class="bh"><span class="kicker">${m.l}${m.court?' · '+m.court:''}</span>${m.st==='live'?'<span class="st no">● En jeu</span>':m.st==='done'?'<span class="st ok">Terminé</span>':'<span class="st wait">À suivre</span>'}</div>${line(0)}${line(1)}${ctl}</div>`}).join('');
  if(live&&S.scoring&&r.ms.every(m=>m.st==='done'))h+=`<button class="btn full" data-a="endrec" data-r="${r.id}">Clôturer la rencontre et publier le résultat</button>`;
  if(live)h+=`<div class="note">${S.scoring?"Chaque jeu ajouté s'affiche aussitôt chez tous les adhérents. Le bouton −1 corrige une erreur, même après la fin d'un set ou d'un match.":can?"Les scores se mettent à jour en direct. Tu peux les saisir depuis le bord du court.":"Les scores se mettent à jour en direct, saisis par le capitaine ou le club."}</div>`}
 if(live&&r.chat)h+=`<div><h2 class="tilt sm">Le <em>direct</em><i class="dd"></i></h2><p class="muted small" style="margin-top:6px">Discussion ouverte le temps de la rencontre. Elle s'efface au dernier point.</p></div><div class="chat" style="padding:0">${r.chat.length?r.chat.map((m,i)=>msgRow(m,i,sport,'r:'+r.id,S.sent&&i===r.chat.length-1)).join(''):'<span class="muted small">Sois le premier à encourager l\'équipe.</span>'}</div>`;
 if(r.st==='soon'){const L=r.lineup||(r.lineup={}),C=r.conv||(r.conv={}),cnt=x=>g.mem.filter(p=>L[p]===x).length,nT=cnt('T'),nR=cnt('R'),stt={ok:['ok','Dispo'],no:['no','Pas dispo'],wait:['wait','En attente']};
  if(L[me])h+=`<div class="card"><span class="kicker">Ta convocation</span><span class="h3">Tu es ${L[me]==='T'?'titulaire':'remplaçant'}</span><div class="ctl"><button class="btn grow ${C[me]==='ok'?'':'ghost'}" data-a="conv" data-r="${r.id}" data-s="ok">Je suis dispo</button><button class="btn grow ${C[me]==='no'?'hot':'ghost'}" data-a="conv" data-r="${r.id}" data-s="no">Pas dispo</button></div></div>`;
  h+=`<div><h2 class="tilt sm">La <em>compo</em><i class="dd"></i></h2><p class="muted small" style="margin-top:6px">${nT} titulaire${nT>1?'s':''} · ${nR} remplaçant${nR>1?'s':''}${can?". Touche Titulaire ou Remplaçant pour convoquer un joueur : il est prévenu et répond dans l'appli.":''}</p></div><div>`
  +g.mem.filter(p=>can||L[p]).map(p=>{const z=stt[C[p]||'wait'];return `<div class="item cv">${av(p,'sm')}<span class="grow"><span class="nm">${name(p)}</span> <span class="bd rk">${sport==='Padel'&&M[p].pl?'Niv '+M[p].pl:M[p].r}</span><br>${L[p]?`<span class="st ${z[0]}">${L[p]==='T'?'Titulaire':'Remplaçant'} · ${z[1]}</span>`:'<span class="st wait">Non convoqué</span>'}</span>${can?`<span class="tri"><button class="btn sm grow ${L[p]==='T'?'':'ghost'}" data-a="lineup" data-r="${r.id}" data-id="${p}" data-s="T" aria-pressed="${L[p]==='T'}">Titulaire</button><button class="btn sm grow ${L[p]==='R'?'':'ghost'}" data-a="lineup" data-r="${r.id}" data-id="${p}" data-s="R" aria-pressed="${L[p]==='R'}">Remplaçant</button></span>`:''}</div>`}).join('')+`</div>`;
  if(!can&&!g.mem.some(p=>L[p]))h+=empty('users','Compo pas encore publiée','Le capitaine la publiera avant la rencontre.');
  if(can){const nw=g.mem.filter(p=>L[p]&&(C[p]||'wait')==='wait').length;h+=`<div class="stack">${nw?`<button class="btn full ghost" data-a="relance" data-r="${r.id}">Relancer ${nw} joueur${nw>1?'s':''} sans réponse</button><p class="muted small">Une relance automatique part aussi la veille de la rencontre.</p>`:''}<button class="btn full" data-a="startRec" data-r="${r.id}">Lancer la rencontre en direct</button><button class="btn full ghost" data-a="delRec" data-r="${r.id}">Supprimer la rencontre</button></div>`}}
 if(r.st==='done'&&can)h+=`<div class="fld"><label for="rec-ph">${r.img?"Remplacer la photo d'équipe":"Ajouter la photo d'équipe"}</label><input type="file" id="rec-ph" data-r="${r.id}" accept="image/*"><span class="muted small">Une seule photo par rencontre. Elle s'affiche aussi sur la publication du résultat.</span></div>`;
 if(r.ms&&r.st==='done')h+=`<div class="note">La discussion du direct est fermée. Pour féliciter les joueurs, commente la publication du résultat sur le mur.</div>`;
 return h+'</div>'}

function champBody(c,edit){const ts=GROUPS.filter(g=>g.champ===c.id);
 return `<div><span class="tags">${sportTag(c.sport)}<span class="tag">${c.age}</span></span><p class="muted small" style="margin-top:6px">${ts.length} équipe${ts.length>1?'s':''} engagée${ts.length>1?'s':''} · ${c.season}</p></div>
 <div>${ts.length?ts.map(g=>{const n=recs.filter(r=>r.tid===g.id&&!r.arch).length;return `<button class="item" data-a="open" data-v="team" data-id="${g.id}"><span class="tile">${ic('users')}</span><span class="grow"><span class="nm">${teamName(g)}</span><br><span class="muted small">${g.sub} · capitaine ${g.cap?first(g.cap):'à désigner'} · ${n} rencontre${n>1?'s':''}</span></span></button>`}).join(''):empty('users','Aucune équipe engagée',edit?'Ajoute la première équipe de ce championnat.':'')}</div>
 ${edit?`<button class="btn full ghost" data-a="newPost" data-k="team" data-c="${c.id}">Ajouter une équipe</button>`:''}`}
/* ---------- résultat final d'une équipe dans son championnat ---------- */
const STAGES=['Vainqueur','Finaliste','Demi-finaliste','Quart de finaliste','8e de finaliste','16e de finaliste'];
const fem=p=>p==='1er'?'1re':p;
function finalPlace(f){const a=[];if(f.fmt!=='Tableau final')a.push(`${fem(f.pp)} de poule sur ${f.pn} équipes`);if(f.fmt!=='Poule')a.push(f.tm==='place'?`${fem(f.tp)} place du tableau final`:f.ts==='Vainqueur'?'Vainqueur du tableau final':f.ts+' au tableau final');return a.join(' · ')}
const finalHead=f=>f.out==='Montée'?`Bravo, l'équipe monte en ${f.div||'division supérieure'} !`:f.out==='Descente'?`L'équipe descend en ${f.div||'division inférieure'}`:`L'équipe se maintient en ${f.from}`;
const finalCard=f=>f?`<div class="card fin ${f.out==='Montée'?'up':f.out==='Descente'?'down':''}"><span class="kicker">Résultat final · saison ${f.season}</span><span class="h3" style="display:block">${finalHead(f)}</span><span class="muted small">${finalPlace(f)}</span>${f.txt?`<p>${esc(f.txt)}</p>`:''}</div>`:'';
function tfPost(p){const g=grp(p.tid),f=p.final;return `<div class="poster ${f.out==='Montée'?'up':''}"><span class="kicker" style="color:var(--fg)">Fin de championnat · ${teamName(g)}</span><span class="big">${f.out==='Montée'?'Montée !':f.out==='Descente'?'Descente':'Maintien'}</span></div><h2 class="h3">${finalHead(f)}</h2><p class="muted small">${f.champ} · ${finalPlace(f)}</p>${f.txt?`<p>${esc(f.txt)}</p>`:''}<button class="btn full ghost" data-a="open" data-v="team" data-id="${g.id}">Voir la saison de l'équipe</button>`}
function teamArch(key){const [id,s]=key.split('|'),g=grp(id),h=(g.hist||[]).find(x=>x.season===s),R=recs.filter(r=>r.arch===s&&r.tid===id);
 return `<div class="pad"><p class="muted small">${champOf(g).name} · saison ${s}</p>${h?finalCard(h):'<div class="note">Le résultat final de cette saison n\'a pas été renseigné.</div>'}<div class="stack"><span class="kicker">Rencontres de la saison · ${R.length}</span>${R.length?R.map(recCard).join(''):empty('cal','Aucune rencontre archivée','')}</div></div>`}
function teamView(id){const g=grp(id),c=champOf(g),cal=recs.filter(r=>r.tid===id&&!r.arch),can=canTeam(g);
 return `<div class="pad"><div><div class="tags" style="display:flex">${teamTags(id)}</div><p class="muted small" style="margin-top:8px">${c.name} · ${g.sub}</p></div>${finalCard(g.final)}
 <div class="stack"><span class="kicker">Calendrier</span>${cal.length?cal.map(recCard).join(''):empty('cal','Aucune rencontre programmée',can?'Ajoute la première ci-dessous.':'')}${g.final?'<p class="muted small">Championnat clôturé : plus aucune rencontre ne peut être ajoutée.</p>':''}</div>
 <div><span class="kicker">Effectif · ${g.mem.length}</span>${g.mem.map(p=>`<div class="item">${av(p,'sm')}<span class="grow">${who(p)} ${bd(p,c.sport)}</span>${p===g.cap&&M[p].role!=='Capitaine'?'<span class="bd cap">Capitaine</span>':''}</div>`).join('')||empty('users','Effectif vide','')}</div>
 ${can?`<div class="card"><span class="kicker">Gérer l'équipe</span><div class="fld"><label for="cap-sel">Capitaine</label><select id="cap-sel" data-team="${id}">${g.mem.map(p=>`<option value="${p}" ${p===g.cap?'selected':''}>${name(p)}</option>`).join('')}</select></div><div class="ctl">${g.final?'':'<button class="btn sm grow" data-a="newPost" data-k="fixture" data-c="'+id+'">Ajouter une rencontre</button>'}<button class="btn sm ghost grow" data-a="open" data-v="grp" data-id="${id}">Gérer l'effectif</button></div><button class="btn sm full ${g.final?'ghost':''}" data-a="teamFinal" data-id="${id}">${g.final?'Modifier le résultat final':'Clôturer le championnat'}</button></div>`:''}</div>`}

/* ---------- planning ---------- */
function planItems(iso){const [y,m,d]=iso.split('-').map(Number),wd=new Date(y,m-1,d).getDay(),out=[],me=ME(),mine=x=>x===me||(M[me].kids||[]).includes(x);
 GROUPS.filter(g=>g.type==='train'&&g.day===wd).forEach(g=>{const cx=(g.cancel||[]).includes(iso);out.push({cat:'ens',sport:g.sport,t:g.h,dur:g.dur==='1 h'?60:90,sub:(cx?'Cours annulé · ':'Cours · ')+g.dur+(g.coach?' · '+first(g.coach):'')+(cx?'':' · '+locOf(g,iso)),title:g.name,cx,v:chans.some(c=>c.id===g.id)?'chan':'grp',id:g.id,my:g.mem.some(mine)||g.coach===me})});
 recs.filter(r=>r.d===iso&&!r.arch).forEach(r=>{const g=grp(r.tid);out.push({cat:'eq',sport:recSport(r),t:r.h,dur:240,sub:r.comp,title:teamName(g)+' – '+r.opp,v:'rec',id:r.id,my:g.mem.some(mine)})});
 posts.filter(p=>p.kind==='event'&&!p.arch&&p.d&&iso>=p.d&&iso<=(p.d2||p.d)&&ruleOk(p.rule)).forEach(p=>{const du=hMin(p.h2)-hMin(p.h1);out.push({cat:'ani',all:!!p.d2,sport:p.sport||'',t:p.d2?'':p.h1,dur:du>0?du:120,sub:p.d2?'Du '+fmtD(p.d,1)+' au '+fmtD(p.d2,1):p.h1+' – '+p.h2+' · '+p.place,title:p.title.replace(/<[^>]+>/g,''),v:'post',id:p.id,my:true})});
 return out.filter(i=>S.plan.cat[i.cat]&&(!i.sport||S.plan.sp[i.sport])&&(i.v!=='grp'||seesMinors())&&(!S.plan.mine||i.my)).sort((a,b)=>hMin(a.t)-hMin(b.t))}
function planGrid(days,detail){const H0=8,H1=23,ph=detail?48:26,hours=[];for(let h=H0;h<H1;h++)hours.push(h);
 const col=iso=>{const its=planItems(iso).filter(i=>!i.all),lanes=[];
  its.forEach(i=>{const s=hMin(i.t),e=s+i.dur;let l=lanes.findIndex(end=>end<=s);if(l<0){l=lanes.length;lanes.push(e)}else lanes[l]=e;i.l=l});const n=lanes.length||1;
  return `<div class="gcol" style="height:${(H1-H0)*ph}px">${its.map(i=>{const top=Math.max(0,(hMin(i.t)/60-H0)*ph),hh=Math.max(i.dur/60*ph,detail?34:12);return `<button class="gev ${i.cat} ${i.cx?'cx':''}" style="top:${top}px;height:${hh}px;left:${i.l*100/n}%;width:${100/n}%" data-a="open" data-v="${i.v}" data-id="${i.id}" aria-label="${i.t} ${esc(i.title)}">${detail?`<b>${i.t}</b>${i.title}`:`<span class="gt">${(i.t||'').replace(/ h ?/,'h')}</span>`}</button>`}).join('')}</div>`};
 const all=iso=>planItems(iso).filter(i=>i.all).map(i=>`<button class="gall ${i.cat}" data-a="open" data-v="${i.v}" data-id="${i.id}" aria-label="${esc(i.title)}">${detail?i.title:''}</button>`).join('');
 return `<div class="grid ${detail?'detail':''}" style="--n:${days.length}"><div class="ghead"><span></span>${days.map(iso=>{const [yy,mm,dd]=iso.split('-').map(Number);return `<button class="gday ${iso===TODAY?'today':''}" data-a="planDay" data-d="${iso}" aria-label="${fmtD(iso)}">${DA[new Date(yy,mm-1,dd).getDay()]}<b>${dd}</b></button>`}).join('')}</div>
 <div class="gallrow"><span></span>${days.map(iso=>`<div>${all(iso)}</div>`).join('')}</div><div class="gbody"><div class="ghours">${hours.map(h=>`<span>${h} h</span>`).join('')}</div>${days.map(col).join('')}</div></div>`}
/* Agenda : planning du club + tout ce qui était dans « École » (cours, stages, gestion des groupes), avec des filtres en haut */
/* Agenda : le planning du club (événements, semaine, jour, liste) */
function agendaView(){return planView()}
function eventsView(){const ev=posts.filter(p=>p.kind==='event'&&!p.stage&&!p.arch&&ruleOk(p.rule)).sort((a,b)=>(a.d||'').localeCompare(b.d||''));
 return `<div class="pad">${ev.length?ev.map(p=>{const [yy,mm,dd]=(p.d||TODAY).split('-').map(Number),sp=postSport(p);return `<div class="card"><div class="row" style="align-items:flex-start;gap:12px"><div class="grow"><span class="h3">${p.title}</span><div class="tags" style="display:flex;margin-top:6px">${sportTag(sp)}${p.done?'<span class="bd done">Terminé</span>':''}</div><p class="muted small" style="margin-top:8px">${p.body}</p></div><span class="dblk"><b>${dd}</b>${MO[mm-1]}</span></div>${evBox(p)}<button class="btn sm ghost" data-a="pmenu" data-id="${p.id}">${ic('more')}Options</button></div>`}).join(''):empty('cal','Aucun événement à venir','Les prochains événements du club apparaîtront ici.')}</div>`}
function myTeamsView(){const me=ME(),who=[me,...(M[me].kids||[])],ts=GROUPS.filter(g=>g.type==='team'&&(g.cap===me||g.mem.some(x=>who.includes(x)))),ids=ts.map(g=>g.id);
 const up=recs.filter(r=>!r.arch&&ids.includes(r.tid)&&r.st!=='done').sort((a,b)=>a.d.localeCompare(b.d)),past=recs.filter(r=>!r.arch&&ids.includes(r.tid)&&r.st==='done').sort((a,b)=>b.d.localeCompare(a.d));
 return `<div class="pad">${ts.length?`<span class="kicker">À venir et en direct</span>${up.length?up.map(recCard).join(''):'<span class="muted small">Aucune rencontre programmée.</span>'}${past.length?`<span class="kicker">Déjà jouées</span>${past.map(recCard).join('')}`:''}<span class="kicker">Mes équipes</span>${ts.map(g=>`<button class="item" data-a="open" data-v="team" data-id="${g.id}"><span class="tile">${ic('users')}</span><span class="grow"><span class="nm">${teamName(g)}</span><br><span class="muted small">${g.sub}${g.cap?' · capitaine '+first(g.cap):''}</span></span></button>`).join('')}`:empty('users','Aucune équipe',"Tu ne fais partie d'aucune équipe cette saison. Les équipes du club sont dans Club, Équipes.")}</div>`}
function planView(){const P=S.plan;const [y,m,d]=P.d.split('-').map(Number),mon=isoIn(-((new Date(y,m-1,d).getDay()+6)%7),P.d),days=[0,1,2,3,4,5,6].map(i=>isoIn(i,mon)),byDay=P.mode==='day';
 const mode=(k,l)=>`<button class="chip" data-a="planMode" data-m="${k}" aria-pressed="${P.mode===k}">${l}</button>`,modes=`<div class="chips">${mode('events','Événements')}${mode('week','Semaine')}${mode('day','Jour')}${mode('list','Liste')}</div>`;
 if(P.mode==='events')return eventsView().replace('<div class="pad">','<div class="pad" id="plan">'+modes);
 const chip=(g2,k,l,c)=>`<button class="chip" data-a="planF" data-g="${g2}" data-k="${k}" aria-pressed="${!!P[g2][k]}">${c?`<i class="sq ${c}"></i>`:''}${l}</button>`;
 const item=i=>`<button class="pit ${i.cat} ${i.cx?'cx':''}" data-a="open" data-v="${i.v}" data-id="${i.id}"><i class="sq"></i><span class="tm">${i.t||'Journée'}</span><span class="grow"><span class="nm">${i.title}</span><br><span class="muted small">${i.sub}</span></span>${sportTag(i.sport)}</button>`;
 const dayBlock=iso=>{const it=planItems(iso);return `<div class="stack"><span class="kicker" ${iso===TODAY?'style="color:var(--accent)"':''}>${fmtD(iso)}${iso===TODAY?" · aujourd'hui":''}</span>${it.length?it.map(item).join(''):'<span class="muted small">Rien de prévu</span>'}</div>`};
 const strip=`<div class="wk">${days.map(iso=>{const n=planItems(iso).length,[yy,mm,dd]=iso.split('-').map(Number);return `<button class="wd ${iso===TODAY?'today':''}" data-a="planDay" data-d="${iso}" aria-pressed="${byDay&&iso===P.d}" aria-label="${fmtD(iso)}"><span>${DA[new Date(yy,mm-1,dd).getDay()]}</span><b>${dd}</b><i>${n||''}</i></button>`}).join('')}</div>`;
 return `<div class="pad" id="plan">${modes}<div class="row" style="justify-content:space-between"><button class="ib rnd" data-a="planNav" data-n="-1" aria-label="${byDay?'Jour précédent':'Semaine précédente'}">${ic('back')}</button><span class="h3">${byDay?fmtD(P.d):'Du '+fmtD(days[0],1)+' au '+fmtD(days[6],1)}</span><button class="ib rnd" style="rotate:180deg" data-a="planNav" data-n="1" aria-label="${byDay?'Jour suivant':'Semaine suivante'}">${ic('back')}</button></div>
 <div class="chips"><button class="chip" data-a="planMine" aria-pressed="${!!P.mine}">${ic('user')}Mes groupes et équipes</button>${chip('cat','ens','Enseignement','ens')}${chip('cat','ani','Animation','ani')}${chip('cat','eq','Équipes','eq')}${chip('sp','Tennis','Tennis')}${chip('sp','Padel','Padel')}</div>
 ${P.mode==='week'?planGrid(days,false)+'<p class="muted small">Touche un bloc pour l\'ouvrir, un jour pour voir son détail. Glisse à gauche ou à droite pour changer de semaine.</p>':byDay?strip+planGrid([P.d],true):strip+days.map(dayBlock).join('')}</div>`}

/* ---------- club ---------- */
const artCard=a=>`<button class="art" data-a="open" data-v="art" data-id="${a.id}">${a.img?`<span class="ph wide" style="background-image:url(${a.img})"></span>`:''}<span class="row" style="gap:8px"><span class="kicker">${a.cat} · ${a.date}</span>${sportTag(a.sport)}</span><span class="h3">${a.title}</span><span class="muted">${a.lead}</span></button>`;
function archView(){const seasons=[...new Set([...arts,...recs,...posts].filter(x=>x.arch).map(x=>x.arch))].sort().reverse();
 if(!seasons.length)return `<div class="pad">${empty('folder','Aucune saison archivée','Les saisons clôturées se rangeront ici.')}</div>`;
 const s=seasons.includes(S.arch.s)?S.arch.s:seasons[0],t=S.arch.t,AR=arts.filter(a=>a.arch===s),R=recs.filter(r=>r.arch===s),E=posts.filter(p=>p.arch===s&&p.kind==='event'),no=empty('folder','Rien dans cette rubrique','Pour la saison '+s+'.');let b='';
 if(t==='arts')b=AR.length?AR.map(artCard).join(''):no;
 const TS=[...GROUPS,...OLDG].filter(g=>g.type==='team'&&((g.hist||[]).some(h=>h.season===s)||R.some(r=>r.tid===g.id)));
 if(t==='recs')b=TS.length?[...CHAMPS,...OLDC.filter(c=>!CHAMPS.includes(c))].map(c=>{const l=TS.filter(g=>g.champ===c.id);return l.length?`<span class="kicker">${c.name}</span>`+l.map(g=>{const h=(g.hist||[]).find(x=>x.season===s),n=R.filter(r=>r.tid===g.id).length;return `<button class="item" data-a="open" data-v="teamarch" data-id="${g.id}|${s}"><span class="tile ${h&&h.out==='Montée'?'up':''}">${ic(h&&h.out==='Montée'?'trophy':'users')}</span><span class="grow"><span class="nm">${teamName(g)}</span><br><span class="muted small">${h?finalHead(h)+' · '+finalPlace(h):'Résultat final non renseigné'} · ${n} rencontre${n>1?'s':''}</span></span></button>`}).join(''):''}).join(''):no;
 if(t==='evs')b=E.length?E.map(p=>{const [y,m,d]=(p.d||TODAY).split('-').map(Number);return `<button class="item" data-a="open" data-v="post" data-id="${p.id}"><span class="dblk"><b>${d}</b>${MO[m-1]}</span><span class="grow"><span class="h3">${p.title}</span><br><span class="muted small">${p.date} · ${p.place}</span></span></button>`}).join(''):no;
 return `<div class="pad"><div class="stack"><span class="kicker">Saison en cours : ${S.season}</span><div class="chips">${seasons.map(x=>`<button class="chip" data-a="arch" data-k="s" data-val="${x}" aria-pressed="${x===s}">${x}</button>`).join('')}</div>
 <div class="chips">${[['arts','Articles',AR.length],['recs','Championnats',TS.length],['evs','Événements',E.length]].map(x=>`<button class="chip" data-a="arch" data-k="t" data-val="${x[0]}" aria-pressed="${x[0]===t}">${x[1]} · ${x[2]}</button>`).join('')}</div></div><div class="stack">${b}</div></div>`}
function teamsBody(){const chip=(k,l)=>`<button class="chip" data-a="recTab" data-k="${k}" aria-pressed="${S.recTab===k}">${l}</button>`,tabs=`<div class="chips">${chip('now','À venir et en cours')}${chip('done','Résultats')}${chip('champ','Championnats')}</div>`;
 if(S.recTab==='champ'){const c=CHAMPS.find(c=>c.id===S.champ)||CHAMPS[0];if(!c)return `<div class="pad">${tabs}${empty('folder','Aucun championnat cette saison',isAdmin()?'Crée les championnats de la nouvelle saison, puis engage les équipes.':'Les équipes de la saison ne sont pas encore engagées.')}${isAdmin()?'<button class="btn full ghost" data-a="newPost" data-k="champ">Créer un championnat</button>':''}</div>`;return `<div class="pad">${tabs}<div class="chips">${CHAMPS.map(x=>`<button class="chip" data-a="champ" data-id="${x.id}" aria-pressed="${x.id===c.id}">${x.name}</button>`).join('')}</div>${champBody(c)}</div>`}
 const list=recs.filter(r=>!r.arch&&(S.recTab==='done'?r.st==='done':r.st!=='done')).sort((a,b)=>S.recTab==='done'?b.d.localeCompare(a.d):a.d.localeCompare(b.d));
 return `<div class="pad">${tabs}${list.length?list.map(recCard).join(''):empty('score',S.recTab==='done'?'Aucun résultat cette saison':'Aucune rencontre à venir','Le calendrier se remplit depuis la page de chaque équipe.')}</div>`}
function clubView(){const I2=CLUBINFO,tl=[I2.mods.actus&&['actus','Actus','news'],['teams','Équipes','users'],['club','Le club','club'],I2.mods.comm&&['comm','Commissions','flag']].filter(Boolean);if(!tl.some(x=>x[0]===S.clubTab))S.clubTab=tl[0][0];const tabs=segs('clubTab',tl),t=S.clubTab;
 if(t==='teams')return tabs+teamsBody();
 if(t==='comm')return tabs+commList();
 if(t==='actus'){const l=arts.filter(a=>!a.arch);return tabs+`<div class="pad">${l.length?l.map(artCard).join(''):empty('news','Pas encore d\'actu cette saison','Les actus du club apparaîtront ici.')}</div>`}
 const lk=(u,l)=>u?`<a class="btn ghost grow" href="${u}" target="_blank" rel="noopener">${l} ${ic('link')}</a>`:'';
 return tabs+`<div class="pad"><div class="poster"><span class="kicker" style="color:var(--fg)">Tennis · Padel · saison ${S.season}</span><span class="big">${club().name.replace(' ','<br>')}</span></div>
 <div class="stats"><div><b>${I2.courts}</b><span>Courts</span></div><div><b>${I2.pistes}</b><span>Pistes padel</span></div><div><b>${I2.members}</b><span>Adhérents</span></div><div><b>${GROUPS.filter(g=>g.type==='team').length}</b><span>Équipes</span></div></div>
 <div class="note">${I2.joined} adhérents sur ${I2.members} ont rejoint l'appli.${isAdmin()?` <button class="nm" data-a="open" data-v="join" style="color:var(--accent)">Inviter les autres</button>`:''}</div>
 <div class="ctl">${S.role==='kid'?'':`<button class="btn grow" data-a="open" data-v="list">${ic('users')}Les adhérents</button>`}<button class="btn ghost grow" data-a="open" data-v="partners">Partenaires</button></div>
 ${I2.book||I2.pay||I2.shop?`<div class="ctl" style="flex-wrap:wrap">${lk(I2.book,'Réserver un court')}${lk(I2.pay,'Payer ma cotisation')}${lk(I2.shop,'Boutique')}</div>`:''}
 <div><h2 class="tilt sm">Formules <em>et tarifs</em><i class="dd"></i></h2><div class="card" style="margin-top:10px;gap:0">${FORM.map(f=>`<div class="price"><span><span class="nm">${f[0]}</span><br><span class="muted small">${f[1]}</span></span><b>${f[2]}</b></div>`).join('')}</div></div>
 <button class="btn full" data-a="toast" data-msg="Demande envoyée au secrétariat du club">Demander une inscription</button>
 <div class="card" style="gap:0"><div class="price"><span class="nm">Club-house</span><span class="muted">${I2.house}</span></div><div class="price"><span class="nm">Secrétariat</span><span class="muted">${I2.secr}</span></div><div class="price"><span class="nm">Adresse</span><span class="muted">${I2.addr}</span></div></div>
 <div><span class="kicker">L'équipe du club</span>${(window.ramTeam?ramTeam():['hugo','sarah','mehdi','marc']).map(p=>`<div class="item">${av(p,'sm')}<span class="grow">${who(p)} ${bd(p)}</span></div>`).join('')}</div>
 <button class="btn full ghost" data-a="open" data-v="archive">${ic('folder')}Archives des saisons</button></div>`}
function listView(){if(S.role==='kid')return `<div class="pad">${empty('users','Liste réservée aux adultes','Les comptes jeunes ne voient pas l\'annuaire du club.')}</div>`;
 const L=S.list,q=L.q.trim().toLowerCase(),ids=Object.keys(M).filter(k=>k!=='club'&&!S.blocked.has(k)&&(!isMinor(k)||seesMinors())&&(L.f==='all'||(L.f==='tennis'?M[k].r!=='NC':M[k].pad!=null))&&(!q||M[k].n.toLowerCase().includes(q)));
 const cmp={tennis:(a,b)=>rIdx(M[b].r)-rIdx(M[a].r),padel:(a,b)=>(M[a].pad||1e9)-(M[b].pad||1e9),name:(a,b)=>M[a].n.localeCompare(M[b].n)};
 if(!cmp[L.sort])L.sort='tennis';ids.sort(cmp[L.sort]);const o=(v,l,cur)=>`<option value="${v}" ${v===cur?'selected':''}>${l}</option>`,sp=L.sort==='padel'||L.f==='padel'?'Padel':'';
 return `<div class="pad"><div class="fld"><label for="l-q">Rechercher un adhérent</label><input id="l-q" type="search" value="${esc(L.q)}" placeholder="Nom ou prénom" autocomplete="off"></div>
 <div class="two"><div class="fld"><label for="l-sort">Trier par</label><select id="l-sort">${o('tennis','Classement tennis',L.sort)}${o('padel','Classement padel',L.sort)}${o('name','Nom',L.sort)}</select></div><div class="fld"><label for="l-f">Pratique</label><select id="l-f">${o('all','Tennis et padel',L.f)}${o('tennis','Tennis',L.f)}${o('padel','Padel',L.f)}</select></div></div>
 ${seesMinors()?'':'<p class="muted small">Les jeunes du club n\'apparaissent pas dans cette liste.</p>'}
 <div id="l-res"><span class="kicker">${ids.length} adhérent${ids.length>1?'s':''}</span>${ids.length?ids.map(p=>`<button class="item" data-a="member" data-id="${p}">${av(p,'sm')}<span class="grow"><span class="nm">${M[p].n}</span> ${bd(p,sp)}<br><span class="muted small">${catOf(p)}${sp&&M[p].pad?' · classement padel n° '+M[p].pad:''}</span></span></button>`).join(''):empty('search','Aucun adhérent trouvé','Vérifie l\'orthographe ou change le filtre.')}</div></div>`}

/* ---------- profil ---------- */
const PLACES=Array.from({length:24},(_,i)=>i?(i+1)+'e':'1er');
const partnerTxt=r=>r.pid?'avec '+name(r.pid):r.ext?'avec '+r.ext:'';
function padelList(id){const m=M[id],self=id===ME(),l=m.pres||[],row=r=>`<div class="res"><span class="wl wide ${r.place==='1er'?'w':'pl'}">${r.place}</span><span class="grow"><span class="nm">${r.cat} · ${r.club}</span>${r.pub!=='Adultes'||r.age?` <span class="bd rk">${r.age||r.pub}</span>`:''}<br><span class="muted small">${r.place==='1er'?'1re':r.place} place · ${partnerTxt(r)} · ${fmtD(r.d)}</span></span></div>`;
 if(!l.length)return empty('ball','Aucun tournoi de padel cette saison',self?'Ajoute ton premier résultat avec le bouton +.':'');
 return self?l.map((r,i)=>`<div class="swipe">${row(r)}<button class="del" data-a="delPres" data-i="${i}" aria-label="Supprimer ce résultat">${ic('trash')}</button></div>`).join('')+'<p class="muted small" style="margin-top:8px">Glisse un résultat vers la gauche pour faire apparaître la corbeille.</p>':l.map(row).join('')}
function resList(id){const m=M[id],self=id===ME(),row=r=>`<div class="res"><span class="wl ${r.w?'w':''}">${r.w?'V':'D'}</span><span class="grow"><span class="nm">${esc(r.opp)}</span> <span class="bd rk">${esc(r.or)}</span>${r.perf?' <span class="bd coach">Perf</span>':''}<br><span class="muted small">${esc(r.ctx)}</span></span><span style="font-variant-numeric:tabular-nums;white-space:nowrap">${esc(r.sc)}</span></div>`;
 if(!m.res.length)return empty('score','Aucun résultat cette saison',self?'Ajoute ton premier résultat avec le bouton +.':'');
 return self?m.res.map((r,i)=>`<div class="swipe">${row(r)}<button class="del" data-a="delRes" data-i="${i}" aria-label="Supprimer ce résultat">${ic('trash')}</button></div>`).join('')+'<p class="muted small" style="margin-top:8px">Glisse un résultat vers la gauche pour faire apparaître la corbeille.</p>':m.res.map(row).join('')}
function contact(id){const self=id===ME(),row=(i,l,v)=>`<div class="ct">${ic(i)}<span class="grow"><span class="muted small">${l}</span><br><span class="v">${v}</span></span></div>`,catRow=row('cal','Catégorie',catOf(id)+(self&&M[id].bd?' · né'+(M[id].g==='F'?'e':'')+' le '+fmtD(M[id].bd,1)+' (visible par toi seul)':''));
 if(self&&isMinor(id))return `<div class="card"><span class="kicker">Mes informations</span>${catRow}<p class="muted small">Compte jeune géré par ${name(M[id].parent)}. Tes coordonnées ne sont jamais affichées.</p></div>`;
 if(self&&id===ME())return `<div class="card"><span class="kicker">Mes informations visibles par les adhérents</span>${catRow}${Object.keys(MYCT).map(k=>`<div class="ct">${ic(MYCT[k][0])}<span class="grow"><span class="muted small">${MYCT[k][1]}</span><br>${esc(MYCT[k][2])||'<span class="muted">Non renseigné</span>'}</span><button class="tg" role="switch" aria-checked="${S.share[k]}" aria-label="Partager : ${MYCT[k][1]}" data-a="share" data-k="${k}"></button></div>`).join('')}<p class="muted small">Tout est masqué par défaut. Active seulement ce que tu acceptes de partager.</p><button class="btn sm ghost" data-a="editMe">Modifier mes informations</button></div>`;
 if(isMinor(id)||S.role==='kid')return '';
 const c=CT[id]||{};
 return `<div class="card"><span class="kicker">Contact</span>${catRow}${c.tel?row('phone','Téléphone',c.tel):''}${c.mail?row('mail','E-mail',c.mail):''}${c.soc?row('at',c.soc[0],c.soc[1]):''}<p class="muted small">${c.tel||c.mail||c.soc?`Les coordonnées affichées sont celles que ${first(id)} a choisi de partager.`:`${first(id)} ne partage pas ses coordonnées.`}</p></div>`}
function profile(id){const m=M[id],self=id===ME(),kid=isMinor(id),f=S.follow.has(id),w=m.res.filter(r=>r.w).length,pf=m.res.filter(r=>r.perf).length,blk=S.blocked.has(id),parent=(M[ME()].kids||[]).includes(id);
 let h=`<div class="pad">${self?'<div id="ramAccount" class="ram-acc" hidden></div>':''}${self&&pending()?lockCard():''}<div class="phero"><div class="row" style="gap:14px">${self?`<label class="avedit" aria-label="Changer ma photo de profil">${av(id)}<span class="cam">${ic('image')}</span><input type="file" id="me-photo" accept="image/*"></label>`:m.photo?`<button class="avbtn" data-a="photo" style="background-image:url(${m.photo})" aria-label="Agrandir la photo de profil">${av(id)}</button>`:av(id)}<div class="grow"><h2 class="tilt">${m.n.replace(' ','<br>')}</h2></div></div>
 <div class="row" style="flex-wrap:wrap;gap:6px">${m.role?`<span class="bd ${RC[m.role]||''}">${m.role}</span>`:''}<span class="muted small">${m.team}</span></div>
 <div class="rtiles">${m.r&&m.r!=='NC'?`<span class="rt tennis"><b>${m.r}</b>Tennis</span>`:''}${m.pl?`<span class="rt padel"><b>Niv ${m.pl}</b>Padel</span>`:''}${m.pad?`<span class="rt"><b>${m.pad}</b>Classement padel</span>`:''}${(!m.r||m.r==='NC')&&!m.pl&&!m.pad?'<span class="rt"><b>NC</b>Non classé</span>':''}</div>
 ${self||kid?'':`<div class="ctl">${blk?`<button class="btn grow ghost" data-a="unblock" data-id="${id}">Débloquer ${first(id)}</button>`:`<button class="btn grow ${f?'on':''}" data-a="follow" data-id="${id}" aria-pressed="${f}">${ic(f?'check':'plus')}${f?'Suivi':'Suivre '+first(id)}</button>`}<button class="ib rnd" data-a="umenu" data-id="${id}" aria-label="Options">${ic('more')}</button></div>`}</div>
 <div class="stats"><div><b>${kid?'—':m.fol+(f?1:0)}</b><span>Abonnés</span></div><div><b>${w}</b><span>Victoires</span></div><div><b>${m.res.length-w}</b><span>Défaites</span></div><div><b>${pf}</b><span>Perfs</span></div></div>${trophyCard(id)}`;
 if(self)h+=`<div class="stack"><div class="ctl"><button class="btn grow" data-a="result">Ajouter un résultat</button>${kid?'':`<button class="btn grow ghost" data-a="newPost" data-k="play">Chercher une partie</button>`}</div><div class="ctl"><button class="btn sm ghost grow" data-a="rank" data-k="tennis">Classement tennis</button><button class="btn sm ghost grow" data-a="rank" data-k="padel">Classement padel</button></div></div>`;
 if(kid&&parent)h+=parentCard(id);
 else if(kid&&!self)h+=`<div class="note">Compte jeune : pas de messagerie privée ni d'abonnés. Ses résultats ne sont visibles que de son groupe, de ses parents et des encadrants.</div>`;
 h+=contact(id)+`<div class="stack"><span class="kicker">Palmarès de la saison</span><div class="chips"><button class="chip" data-a="palm" data-s="tennis" aria-pressed="${S.palm!=='padel'}">Tennis · ${m.res.length}</button><button class="chip" data-a="palm" data-s="padel" aria-pressed="${S.palm==='padel'}">Padel · ${(m.pres||[]).length}</button></div><div>${S.palm==='padel'?padelList(id):resList(id)}</div></div>`;
 if(self){const N=[['club','Annonces et événements du club'],['follow','Résultats des adhérents que je suis'],['chan','Messages dans mes groupes'],['team','Convocations et scores de mon équipe'],['live','Détail des matchs en direct (chaque match, pas seulement le début et la fin de la rencontre)'],['play','Recherches de partie à mon niveau et joueurs qui rejoignent les miennes'],['mine','Likes, commentaires et réactions à mes publications et messages']];
  h+=`<div class="card"><span class="kicker">Fond de l'appli</span><div class="motifs">${MOTIFS.map(([k,l])=>`<button data-a="motif" data-k="${k}" aria-pressed="${S.motif===k}"><i class="${k}"></i>${l}</button>`).join('')}</div><p class="muted small">Le motif reste immobile derrière le contenu.</p></div>`;
  h+=`<div class="card"><span class="kicker">Mes notifications</span>${N.map(x=>`<div class="ct"><span class="grow">${x[1]}</span><button class="tg" role="switch" aria-checked="${S.nset[x[0]]}" aria-label="${x[1]}" data-a="nset" data-k="${x[0]}"></button></div>`).join('')}<div class="ct"><span class="grow">Notifications sur ce téléphone<br><span class="muted small">Même quand l'appli est fermée${/iPhone|iPad|iPod/.test(navigator.userAgent)&&!navigator.standalone?' · sur iPhone, installe d\'abord l\'appli':''}</span></span><button class="btn sm ghost" data-a="pushOn">Activer</button></div>${/iPhone|iPad|iPod/.test(navigator.userAgent)&&!navigator.standalone&&document.querySelector('link[rel="manifest"]')?'<button class="btn sm ghost full" data-a="installHelp">Installer l\'appli sur l\'écran d\'accueil</button>':''}<div class="ct"><span class="grow">Sons de l'appli<br><span class="muted small">Like, message, notification, trophée</span></span><button class="tg" role="switch" aria-checked="${!!S.sound}" aria-label="Sons de l'appli" data-a="sound"></button></div></div>`;
  if(id===ME())h+=`<div class="card"><span class="kicker">Ma famille</span>${(m.kids||[]).map(k=>`<button class="item" data-a="member" data-id="${k}">${av(k,'sm')}<span class="grow"><span class="nm">${M[k].n}</span> ${bd(k)}<br><span class="muted small">${catOf(k)} · ${M[k].team}</span></span></button>`).join('')}<button class="btn sm ghost" data-a="addKid">Ajouter un enfant</button></div>`;
  h+=`${window.RAM_KEY?(isAdmin()?`<div class="card"><span class="kicker">Apparence du club</span><p class="muted small">Nom, sigle, logo et couleur, visibles par tous les adhérents.</p><button class="btn sm ghost" data-a="look">Personnaliser</button></div>`:''):`<div class="card"><span class="kicker">Démo · voir l'appli en tant que</span><div class="chips">${[['admin','Bureau'],['cap','Capitaine'],['mem','Adhérent et parent'],['coach','Enseignante'],['kid','Jeune (Léo)'],['wait','Nouvel inscrit (Lucas)']].map(x=>`<button class="chip" data-a="role" data-r="${x[0]}" aria-pressed="${S.role===x[0]}">${x[1]}</button>`).join('')}</div><p class="muted small">Le bureau voit tout et gère le club. Le capitaine gère son équipe. L'enseignante gère ses groupes (appel, annulation). L'adhérent et le jeune ne voient que ce qui leur est destiné.</p></div>
  <div class="card"><span class="kicker">Démo · les couleurs du club</span><div class="sw">${CLUBS.map((c,i)=>`<button data-a="theme" data-i="${i}" aria-pressed="${S.club===i}"><i><span style="background:${c.bg||(c.dark?'#0B0B0B':'#F3F5FA')}"></span><span style="background:${c.accent}"></span></i>${c.label}</button>`).join('')}</div>${isAdmin()?`<button class="btn sm ghost" data-a="look">Personnaliser nom, logo et couleur</button>`:''}</div>`}
  <div class="menu"><button data-a="open" data-v="legal">${ic('shield')}Conditions et confidentialité</button>${kid?'':`<button class="danger" data-a="delAccount">${ic('trash')}Supprimer mon compte</button>`}</div>${kid?'<p class="muted small">Seul ton parent peut supprimer ton compte.</p>':''}
  <div class="powered"><span>Propulsé par</span><img src="${ramLogo()}" alt="/RAM Club"></div>`}
 return h+'</div>'}
/* Espace parent : prochains cours de l'enfant, absences, autorisation photo, second parent */
const nextSessionOf=g=>{for(let i=0;i<7;i++){const iso=isoIn(i),[y,m,d]=iso.split('-').map(Number);if(new Date(y,m-1,d).getDay()===g.day)return iso}return TODAY};
function nextSessions(k,n){const out=[];GROUPS.filter(g=>g.type==='train'&&g.mem.includes(k)).forEach(g=>{let c=0;for(let i=0;i<15&&c<n;i++){const iso=isoIn(i),[y,m,d]=iso.split('-').map(Number);if(new Date(y,m-1,d).getDay()===g.day){out.push({g,iso});c++}}});return out.sort((a,b)=>a.iso.localeCompare(b.iso))}
function parentCard(k){const kd=M[k],ss=nextSessions(k,2),rr=recs.filter(r=>!r.arch&&r.st!=='done'&&grp(r.tid).mem.includes(k));
 return `<div class="card"><span class="kicker">Espace parent · ${first(k)}</span>${ss.map(s=>{const cx=(s.g.cancel||[]).includes(s.iso),ab=((s.g.abs||{})[s.iso]||[]).includes(k);return `<div class="ct">${ic('cal')}<span class="grow"><span class="nm">${s.g.name}</span><br><span class="muted small">${fmtD(s.iso)} · ${s.g.h}${cx?' · cours annulé':ab?' · absence signalée':''}</span></span></div>`}).join('')||'<p class="muted small">Aucun cours dans les 15 prochains jours.</p>'}${rr.map(r=>`<div class="ct">${ic('users')}<span class="grow"><span class="nm">${teamName(grp(r.tid))} – ${r.opp}</span><br><span class="muted small">${r.when}</span></span></div>`).join('')}
 <div class="ctl"><button class="btn sm grow" data-a="absence" data-id="${k}">Signaler une absence</button><button class="btn sm ghost grow" data-a="parent2" data-id="${k}">Second parent</button></div>
 <div class="ct"><span class="grow"><span class="nm">Autorisation photo</span><br><span class="muted small">${kd.photoOk?'Le club peut publier des photos où apparaît '+first(k)+'.':'Le club ne doit publier aucune photo où apparaît '+first(k)+'.'}</span></span><button class="tg" role="switch" aria-checked="${!!kd.photoOk}" aria-label="Autorisation photo pour ${first(k)}" data-a="photoOk" data-id="${k}"></button></div>
 <div class="fld"><span class="lb">Résultats de ${first(k)} visibles par</span><div class="chips"><button class="chip" data-a="kidVis" data-id="${k}" data-v="grp" aria-pressed="${kd.resVis!=='club'}">Son groupe et ses encadrants</button><button class="chip" data-a="kidVis" data-id="${k}" data-v="club" aria-pressed="${kd.resVis==='club'}">Tout le club</button></div></div>
 <button class="btn sm ghost" style="color:var(--hot-tx)" data-a="kidDel" data-id="${k}">Supprimer le compte de ${first(k)}</button></div>`}

/* ---------- école : séances datées, lieu, présences ---------- */
function sessions(g,days){const out=[];for(let i=0;i<days;i++){const iso=isoIn(i),[y,m,d]=iso.split('-').map(Number);if(new Date(y,m-1,d).getDay()===g.day)out.push(iso)}return out}
const locOf=(g,iso)=>(g.loc||{})[iso]||g.defLoc||'Extérieur';
const respOf=(g,iso,id)=>((g.resp||{})[iso]||{})[id]||(((g.abs||{})[iso]||[]).includes(id)?'no':'');
function sessCard(g,iso,who,manage){const cx=(g.cancel||[]).includes(iso),loc=locOf(g,iso),[y,m,d]=iso.split('-').map(Number),r=who?respOf(g,iso,who):'',nOk=g.mem.filter(p=>respOf(g,iso,p)==='ok').length,nNo=g.mem.filter(p=>respOf(g,iso,p)==='no').length;
 return `<div class="card"><div class="row" style="align-items:flex-start;gap:12px"><span class="dblk"><b>${d}</b>${MO[m-1]}</span><div class="grow"><span class="h3" style="font-size:19px">${g.name}</span><br><span class="muted small">${DA[new Date(y,m-1,d).getDay()]} · ${g.h} · ${g.dur}${g.coach?' · '+first(g.coach):''}</span><div class="tags" style="display:flex;margin-top:6px">${cx?'<span class="tag" style="background:var(--hot);color:#fff">Cours annulé</span>':`<span class="tag loc">${ic(loc==='En salle'?'home':'sun')}${loc}</span>`}${sportTag(g.sport)}${who&&who!==ME()?`<span class="tag">${first(who)}</span>`:''}</div></div></div>`
 +(cx||!who?'':`<div class="ctl"><button class="btn sm grow ${r==='ok'?'':'ghost'}" data-a="cresp" data-g="${g.id}" data-d="${iso}" data-u="${who}" data-s="ok">${who===ME()?'Je serai présent':first(who)+' sera présent'}</button><button class="btn sm grow ${r==='no'?'hot':'ghost'}" data-a="cresp" data-g="${g.id}" data-d="${iso}" data-u="${who}" data-s="no">Absent</button></div>`)
 +(manage?`<span class="muted small">${nOk} présent${nOk>1?'s':''} annoncé${nOk>1?'s':''} · ${nNo} absent${nNo>1?'s':''} · ${g.mem.length} élève${g.mem.length>1?'s':''}</span><div class="ctl" style="flex-wrap:wrap">${cx?'':`<button class="btn sm grow ghost" data-a="loc" data-g="${g.id}" data-d="${iso}">${loc==='En salle'?'Passer en extérieur':'Passer en salle'}</button>`}<button class="btn sm grow ${cx?'':'ghost'}" data-a="cancelCourse" data-id="${g.id}" data-d="${iso}">${cx?'Rétablir le cours':'Annuler'}</button><button class="btn sm grow" data-a="open" data-v="grp" data-id="${g.id}">Appel</button></div>`:'')+`</div>`}
/* « Premiers pas » du bureau : 5 étapes cochées toutes seules, chacune ouvre son écran ; disparaît quand tout est fait */
function setupCard(){if(!isBureau())return '';const st=S.setup||{},steps=[
 ['Identité du club','Nom, logo et couleurs',!!st.look||!!club().logo,'data-a="look"'],
 ['Infos et tarifs','Courts, contacts, formules et prix',!!st.info,'data-a="clubInfo"'],
 ['Championnats et équipes','Engager les équipes de la saison',CHAMPS.length>0&&GROUPS.some(g=>g.type==='team'),'data-a="setupGo" data-k="champ"'],
 ["Groupes d'entraînement",'Créés par les enseignants, visibles dans l\'Agenda',GROUPS.some(g=>g.type==='train'),'data-a="setupGo" data-k="train"'],
 ['Adhérents invités','Code du club, lien ou import de liste',(S.invited||0)>0||!!st.inv,'data-a="open" data-v="join"']],n=steps.filter(s=>s[2]).length;
 if(n===steps.length)return '';
 return `<div class="card setup"><span class="kicker">Premiers pas · ${n} sur ${steps.length}</span><span class="bar"><i style="width:${n*100/steps.length}%"></i></span>${steps.map(s=>`<button class="item" ${s[3]}><span class="chk ${s[2]?'on':''}" aria-hidden="true">${s[2]?ic('check'):''}</span><span class="grow"><span class="nm">${s[0]}</span><br><span class="muted small">${s[1]}</span></span><span class="sr">${s[2]?'fait':'à faire'}</span></button>`).join('')}</div>`}
/* ---------- compte en attente de validation pour la saison ---------- */
const lockOk=v=>v.v==='me'||v.v==='legal'||((v.v==='member'||v.v==='trophies')&&(!v.id||v.id===ME()))||(v.v==='troph'&&(v.id||'').split('|')[0]===ME());
function lockCard(){const me=ME(),req=JOINREQ.some(j=>j.id===me),back=!!VALID[me];
 return `<div class="card lockc"><span class="kicker">Accès en attente · saison ${S.season}</span>${req?`<p>${back?'Ta demande de reprise d\'adhésion':'Ta demande d\'inscription'} a bien été envoyée. Le bureau du club doit la valider : tu seras prévenu dès que c'est fait.</p>`:`<p>Ton adhésion de la saison ${VALID[me]} est terminée. Si tu as repris ta licence au club, préviens le bureau pour retrouver l'accès.</p><button class="btn full" data-a="readh">J'ai repris mon adhésion</button>`}</div>`}
function lockView(v){const home=!v.id&&v.v==='home';
 return `<div class="pad"><div class="lockv"><span class="tile big">${ic('shield')}</span><h2 class="h3">${home?'Bienvenue au club':'Page pas encore accessible'}</h2><p>${home?`Vous devez attendre que le club valide votre accès au club pour la saison sportive ${S.season}.`:`Ton compte doit être activé pour la saison sportive ${S.season} pour accéder à cette page. En attendant, tu as accès à ton profil.`}</p></div>${lockCard()}<button class="btn full ghost" data-a="tab" data-t="me">Voir mon profil</button></div>`}
/* Contenu de l'ancien onglet École, affiché par les filtres de l'Agenda */
function ecoleBody(t){const me=ME(),staff=isAdmin(),coach=S.role==='coach';let b='';if(t==='manage'&&!staff)t='mine';
  if(t==='mine'){const whos=[me].concat(M[me].kids||[]),items=[];GROUPS.filter(g=>g.type==='train').forEach(g=>{whos.forEach(w=>{if(g.mem.includes(w))sessions(g,21).forEach(iso=>items.push({g,iso,w}))});if(g.coach===me)sessions(g,21).forEach(iso=>items.push({g,iso,w:null,c:1}))});items.sort((a,b)=>a.iso.localeCompare(b.iso)||hMin(a.g.h)-hMin(b.g.h));
   b=items.length?`<p class="muted small">Tes cours des trois prochaines semaines. Indique ta présence : l'enseignant prépare la séance en conséquence, et tu es notifié si le lieu change ou si le cours est annulé.</p>`+items.map(x=>sessCard(x.g,x.iso,x.w,x.c)).join(''):empty('school','Aucun cours',"Tu n'es inscrit à aucun groupe d'entraînement. Les formules sont dans Club, Le club.")}
  if(t==='stages'){const st=posts.filter(p=>p.stage&&!p.arch);b=(st.length?st.map(p=>`<div class="card"><span class="h3">${p.title}</span><p class="muted small">${p.body}</p>${evBox(p)}</div>`).join(''):empty('ball','Aucun stage prévu',''))+(staff?`<button class="btn full ghost" data-a="newPost" data-k="stage">Créer un stage</button>`:'')}
  if(t==='manage'){const gs=GROUPS.filter(g=>g.type==='train'&&(coach?g.coach===me:true));
   b=`${coach?`<div class="ctl"><button class="btn grow" data-a="newPost" data-k="train">Créer un groupe</button><button class="btn grow ghost" data-a="newPost" data-k="stage">Créer un stage</button></div>`:'<div class="note">Les groupes d\'entraînement sont créés par les enseignants.</div>'}<span class="kicker">Planning des cours · 2 semaines</span>`
   +(gs.flatMap(g=>sessions(g,14).map(iso=>({g,iso}))).sort((a,b)=>a.iso.localeCompare(b.iso)||hMin(a.g.h)-hMin(b.g.h)).map(x=>sessCard(x.g,x.iso,null,1)).join('')||empty('cal','Aucun cours',''))
   +`<span class="kicker">Groupes</span>`+gs.map(g=>`<button class="item" data-a="open" data-v="grp" data-id="${g.id}"><span class="tile">${ic('users')}</span><span class="grow"><span class="nm">${g.name}</span><br><span class="muted small">${g.mem.length} élève${g.mem.length>1?'s':''} · ${g.sub} · ${g.defLoc||'Extérieur'}</span></span></button>`).join('')}
 return b}
