 club:clubView,list:listView,
 art(id){const a=arts.find(a=>a.id===id);return `<div class="pad"><div class="row" style="gap:8px"><span class="kicker">${a.cat} · ${a.date}</span>${sportTag(a.sport)}</div><h2 class="tilt">${a.title}</h2>${a.img?`<button class="ph wide" style="background-image:url(${a.img})" data-a="photo" aria-label="Photo de l'article"></button>`:''}<div class="prose"><p><b>${a.lead}</b></p>${a.body.map(p=>`<p>${p}</p>`).join('')}</div>${isAdmin()&&!a.arch?`<button class="btn full ghost" data-a="delArt" data-id="${a.id}">Supprimer l'article</button>`:''}</div>`},
