  const grps=type=>GROUPS.filter(g=>g.type===type).map(g=>it('open','users',g.name,`${g.mem.length} membre${g.mem.length>1?'s':''} · ${g.sub}`,`data-v="grp" data-id="${g.id}"`)).join('');
  if(false){const mine=[];return `<div class="pad"><div class="note">En tant qu'enseignante, tu gères tes groupes : appel, annulation d'un cours, message au groupe.</div><div><span class="kicker">Mes groupes</span>${mine.map(g=>it('open','ball',g.name,g.sub,`data-v="grp" data-id="${g.id}"`)).join('')}</div></div>`}
